const fs = require('fs');
const os = require('os');
const path = require('path');
if (typeof inputs.markdown !== 'string') { throw new Error('markdown input required'); }
let markdownContent = inputs.markdown;
let tmpMdPath = path.join(os.tmpdir(), `tmp_${Date.now()}.md`);
fs.writeFileSync(tmpMdPath, markdownContent);
let pdfPath = inputs.output_path || path.join(process.cwd(), 'output.pdf');

const markdownPdf = require('markdown-pdf');
await new Promise((resolve, reject) => {
  markdownPdf().from(tmpMdPath).to(pdfPath, err => {
    if (err) reject(err); else resolve();
  });
});
